import React, { useLayoutEffect, useMemo, useRef, useState } from 'react';

import { ChartToolsIcon } from '@dynatrace/strato-icons';

import { HiddenMenu } from './HiddenMenu.js';
import { Button } from '../../../../../buttons/button/Button.js';
import { Menu } from '../../../../../navigation/menu/Menu.js';
import { Tooltip } from '../../../../../overlays/tooltip/Tooltip.js';
import { Divider } from '../../../../../typography/Divider.js';

interface ChartToolbarMenuProps {
  children: React.ReactNode;
  onMenuOpen: (open: boolean) => void;
}

function renderMenuItems(children: React.ReactNode): React.ReactNode {
  return React.Children.map(children, (child) => {
    if (React.isValidElement(child)) {
      if (child.type === Divider) {
        // We render the divider as horizontal instead of vertical for the menu
        return <Divider orientation="horizontal" as="hr" />;
      }

      if (child.type === React.Fragment) {
        return renderMenuItems(child.props.children);
      }

      return React.cloneElement(child, {
        ...child.props,
        isMenuElement: true,
      });
    }

    return child;
  });
}

/**
 * ChartToolbarMenu component for displaying a dropdown menu
 */
export const ToolbarMenu = (props: ChartToolbarMenuProps) => {
  const { children, onMenuOpen } = props;
  const [isHoverChartToolsIcon, setIsHoverChartToolsIcon] =
    useState<boolean>(false);

  const menuItems = useMemo(() => renderMenuItems(children), []);

  const contentRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    if (contentRef.current) {
      contentRef.current.style.display = 'none';
    }
  }, []);

  const chartActionsButton = useMemo(
    () => (
      <Tooltip text="Chart tools" open={isHoverChartToolsIcon}>
        <Menu.Trigger>
          <Button
            onMouseEnter={() =>
              setIsHoverChartToolsIcon(!isHoverChartToolsIcon)
            }
            onMouseLeave={() =>
              setIsHoverChartToolsIcon(!isHoverChartToolsIcon)
            }
            variant="default"
          >
            <Button.Prefix>{<ChartToolsIcon />}</Button.Prefix>
          </Button>
        </Menu.Trigger>
      </Tooltip>
    ),
    [isHoverChartToolsIcon],
  );

  return (
    <>
      <Menu onOpenChange={onMenuOpen}>
        {chartActionsButton}
        <Menu.Content>
          <Menu.Group>{menuItems}</Menu.Group>
        </Menu.Content>
      </Menu>
      <HiddenMenu menuItems={menuItems} />
    </>
  );
};
